import re
import sys
import json

ANSI = re.compile(r"\x1b\[[0-9;]*m")
PREFIX = re.compile(r"^\(TaskRunner pid=\d+\)\s*")


def parse(path):
    steps = {}
    with open(path, "r", errors="replace") as f:
        for line in f:
            line = ANSI.sub("", line).rstrip("\n")
            line = PREFIX.sub("", line)
            m = re.match(r"^step:(\d+) - (.*)$", line)
            if not m:
                continue
            step = int(m.group(1))
            rest = m.group(2)
            metrics = {}
            for item in rest.split(" - "):
                k, _, v = item.partition(":")
                try:
                    metrics[k] = float(v)
                except ValueError:
                    metrics[k] = v
            steps[step] = metrics
    return steps


if __name__ == "__main__":
    allsteps = {}
    for p in sys.argv[1:]:
        allsteps.update(parse(p))
    json.dump(allsteps, open("/tmp/autorl_analysis/metrics.json", "w"), indent=1)
    keys = sorted({k for m in allsteps.values() for k in m})
    print("n_steps", len(allsteps), "steps:", sorted(allsteps))
    print("n_keys", len(keys))
    for k in keys:
        print(k)

